class Solution {
    public int findLucky(int[] arr){
        Map<Integer,Integer> count=new HashMap<>();
        for(int value:arr)count.merge(value,1,Integer::sum);
        int answer=-1;
        for(Map.Entry<Integer,Integer> entry:count.entrySet())if(entry.getKey().equals(entry.getValue()))answer=Math.max(answer,entry.getKey());
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findLucky(arr:IntArray):Int{
        val count=arr.toList().groupingBy{
            it
        }.eachCount();
        return count.filter{
            it.key==it.value
        }.keys.maxOrNull()?:-1
    }
}

code.cpp:
class Solution {
    public: int findLucky(vector<int>& arr){
        unordered_map<int,int> count;
        for(int value:arr)++count[value];
        int answer=-1;
        for(auto [value,frequency]:count)if(value==frequency)answer=max(answer,value);
        return answer;
    }
};
